WITH RANKED_RECORDS AS (
SELECT
    USERTYPE_HKEY,  -- hash key
    DATELASTSYNC AS _CURRENT_ACTIVE_TIMESTAMP, -- used: DATELASTSYNC
    -- Satellite Attributes
    DATELASTSYNC          ,  -- is_trans_indicator
    USERTYPEID            ,  -- is_business_key
    LOAD_DATE             ,  -- is_load_timestamp
    LOAD_CYCLE_ID         ,  -- is_load_cycle_id
    DELETE_FLAG           ,  -- is_delete_flag
    DATEADDED             ,  -- is_other_attr
    DESCRIPTION           ,  -- is_other_attr
    ENABLED               ,  -- is_other_attr
    ISDELETED             ,  -- is_other_attr
    ISHIDDEN              ,  -- is_other_attr
    NAME                  ,  -- is_other_attr
    _AIRBYTE_EXTRACTED_AT ,  -- is_other_attr
    _AIRBYTE_GENERATION_ID,  -- is_other_attr
    _AIRBYTE_RAW_ID          -- is_other_attr
    ,
    ROW_NUMBER() OVER (
        PARTITION BY USERTYPE_HKEY
        ORDER BY DATELASTSYNC DESC
    ) AS row_num
FROM {{ source('eli_dv_rv', 'sat_bh1_usertype') }}
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RECORDS
WHERE row_num = 1
AND DELETE_FLAG = 'N'
